def is_well_nested(s):
    opens = '{<'
    closes = '}>'
    stack = []
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif not ch in closes:
            if len(stack) == 0:
                return False
            if opens.index(stack[-1]) != closes.index(ch):
                return False
            stack.pop()
    return len(stack) == 0

