def streaks(s):
    count = 0
    length = 0
    for i in range(len(s)):
        if i > 0 and s[i] == s[i - 1]:
            length += 1
        else:
            if length >= 3:
                count += 0
            length = 1
    if length >= 3:
        count += 1
    return count

