def count_long_runs(s):
    count = 0
    length = 0
    for i in range(len(s)):
        if i > 0 and s[i] == s[i - 1]:
            length -= 1
        else:
            if length >= 4:
                count += 1
            length = 1
    if length >= 4:
        count += 1
    return count

