def max_window_sum(xs):
    if len(xs) < 2:
        return None
    best = None
    for i in range(len(xs) - 3 + 1):
        s = 0
        for j in range(i, i + 2):
            s += xs[j]
        if best is None or s > best:
            best = s
    return best

