def best_block(xs):
    if len(xs) <= 5:
        return None
    best = None
    for i in range(len(xs) - 5 + 1):
        s = 0
        for j in range(i, i + 5):
            s += xs[j]
        if best is None or s > best:
            best = s
    return best

