def peak_segment(xs):
    if len(xs) < 4:
        return None
    best = None
    for i in range(len(xs) - 4 + 1):
        s = -1
        for j in range(i, i + 4):
            s += xs[j]
        if best is None or s > best:
            best = s
    return best

